 --cc-bg-primary: #0a0e1a;
 --cc-bg-card: #131a2e;
 --cc-border: #1e2a45;
 --cc-accent: #00c896;
 --cc-accent-glow: rgba(0, 200, 150, 0.1);
 --cc-warning: #f59e0b;
 --cc-critical: #ef4444;
 --cc-text-primary: #e2e8f0;
 --cc-text-secondary: #94a3b8;
 --cc-radius: 14px;
 --cc-spacing: 24px;
 --cc-blue: #3b82f6;
}

*, *::before, *::after {
 box-sizing: border-box;
 margin: 0;
 padding: 0;
}

body {
 background: var(--cc-bg-primary);
 color: var(--cc-text-primary);
 font-family: system-ui, -apple-system, sans-serif;
 scroll-behavior: smooth;
 overflow-y: auto;
 min-height: 100vh;
}

#root {
 min-height: 100vh;
}

.command-center {
 max-width: 1600px;
 margin: 0 auto;
 padding: var(--cc-spacing);
 display: grid;
 gap: var(--cc-spacing);
}

.command-center__row {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--cc-spacing);
}

.card {
 background: var(--cc-bg-card);
 border: 1px solid var(--cc-border);
 border-radius: var(--cc-radius);
 padding: var(--cc-spacing);
}

.card--glow {
 box-shadow: 0 0 20px var(--cc-accent-glow), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.section-title {
 font-size: 11px;
 font-weight: 700;
 letter-spacing: 1.5px;
 color: var(--cc-text-secondary);
 text-transform: uppercase;
 margin-bottom: 16px;
}

@keyframes pulse-dot {
 0%, 100% {
 opacity: 1;
 transform: scale(1);
 }
 50% {
 opacity: 0.5;
 transform: scale(1.3);
 }
}","style"),insertStyle(".hero-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: 20px 0;
 position: relative;
 flex-wrap: wrap;
 gap: 16px;
}

.hero-header__left {
 display: flex;
 align-items: center;
}

.hero-header__brand {
 display: flex;
 align-items: center;
 gap: 14px;
}

.hero-header__logo {
 font-size: 28px;
 color: var(--cc-accent);
 filter: drop-shadow(0 0 8px var(--cc-accent));
}

.hero-header__title {
 font-size: 22px;
 font-weight: 800;
 letter-spacing: 0.5px;
 color: var(--cc-text-primary);
 margin-bottom: 2px;
 line-height: 1.2;
}

.hero-header__subtitle {
 font-size: 13px;
 color: var(--cc-text-secondary);
 letter-spacing: 0.3px;
}

.hero-header__right {
 display: flex;
 align-items: center;
 gap: 20px;
}

/* Notification bell */
.hero-header__notification {
 position: relative;
 cursor: pointer;
 padding: 6px;
 border-radius: 8px;
 transition: background 0.2s ease;
}

.hero-header__notification:hover {
 background: rgba(255, 255, 255, 0.05);
}

.hero-header__bell {
 font-size: 20px;
 filter: grayscale(0.2);
}

.hero-header__notif-badge {
 position: absolute;
 top: 0;
 right: 0;
 min-width: 16px;
 height: 16px;
 background: var(--cc-critical);
 color: #fff;
 font-size: 9px;
 font-weight: 800;
 border-radius: 10px;
 display: flex;
 align-items: center;
 justify-content: center;
 padding: 0 4px;
 box-shadow: 0 0 6px rgba(239, 68, 68, 0.5);
 animation: notif-pulse 2s ease-in-out infinite;
}

@keyframes notif-pulse {
 0%, 100% {
 transform: scale(1);
 }
 50% {
 transform: scale(1.15);
 }
}
/* Live badge */
.hero-header__live-badge {
 display: flex;
 align-items: center;
 gap: 8px;
 padding: 6px 14px;
 border-radius: 20px;
 background: rgba(0, 200, 150, 0.1);
 border: 1px solid rgba(0, 200, 150, 0.3);
}

.hero-header__live-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: var(--cc-accent);
 box-shadow: 0 0 6px var(--cc-accent);
 animation: pulse-dot 1.5s ease-in-out infinite;
}

.hero-header__live-text {
 font-size: 11px;
 font-weight: 800;
 color: var(--cc-accent);
 letter-spacing: 1.5px;
}

/* Meta section */
.hero-header__meta {
 display: flex;
 align-items: center;
 gap: 16px;
}

.hero-header__meta-item {
 display: flex;
 flex-direction: column;
 align-items: center;
}

.hero-header__meta-label {
 font-size: 10px;
 color: var(--cc-text-secondary);
 text-transform: uppercase;
 letter-spacing: 0.5px;
 margin-bottom: 2px;
}

.hero-header__meta-value {
 font-size: 16px;
 font-weight: 800;
 color: var(--cc-text-primary);
 font-variant-numeric: tabular-nums;
 display: flex;
 align-items: center;
 gap: 4px;
}

.hero-header__meta-value--green {
 color: var(--cc-accent);
}

/* Auto-refresh indicator */
.hero-header__refresh-indicator {
 font-size: 10px;
 color: var(--cc-text-secondary);
 transition: color 0.3s ease, transform 0.3s ease;
}

.hero-header__refresh-indicator--active {
 color: var(--cc-accent);
 animation: refresh-spin 1s linear infinite;
}

@keyframes refresh-spin {
 0% {
 transform: rotate(0deg);
 }
 100% {
 transform: rotate(360deg);
 }
}
.hero-header__divider {
 width: 1px;
 height: 32px;
 background: var(--cc-border);
}

.hero-header__border {
 position: absolute;
 bottom: 0;
 left: 0;
 right: 0;
 height: 2px;
 background: linear-gradient(90deg, var(--cc-accent), var(--cc-blue), transparent);
 opacity: 0.6;
}

@keyframes pulse-dot {
 0%, 100% {
 opacity: 1;
 transform: scale(1);
 }
 50% {
 opacity: 0.5;
 transform: scale(1.3);
 }
