 background: var(--cc-bg-card);
 border: 1px solid var(--cc-border);
 border-radius: var(--cc-radius);
 padding: 36px 40px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 40px;
 position: relative;
 overflow: hidden;
 box-shadow: 0 0 40px var(--cc-accent-glow), 0 0 80px rgba(0, 200, 150, 0.05);
}

.pulse-hero::before {
 content: "";
 position: absolute;
 inset: 0;
 border-radius: var(--cc-radius);
 opacity: 0.07;
 pointer-events: none;
}

.pulse-hero--healthy::before {
 background: radial-gradient(ellipse at 20% 50%, var(--cc-accent), transparent 60%);
}

.pulse-hero--warning::before {
 background: radial-gradient(ellipse at 20% 50%, var(--cc-warning), transparent 60%);
}

.pulse-hero--critical::before {
 background: radial-gradient(ellipse at 20% 50%, var(--cc-critical), transparent 60%);
}

.pulse-hero__main {
 display: flex;
 align-items: center;
 gap: 32px;
 flex-shrink: 0;
}

.pulse-hero__ring-container {
 position: relative;
 width: 140px;
 height: 140px;
 flex-shrink: 0;
}

.pulse-hero__ring {
 width: 100%;
 height: 100%;
 transform: rotate(-90deg);
}

.pulse-hero__ring-bg {
 fill: none;
 stroke: var(--cc-border);
 stroke-width: 6;
}

.pulse-hero__ring-fill {
 fill: none;
 stroke: var(--cc-accent);
 stroke-width: 6;
 stroke-linecap: round;
 transition: stroke-dasharray 0.6s ease;
}

.pulse-hero--warning .pulse-hero__ring-fill {
 stroke: var(--cc-warning);
}

.pulse-hero--critical .pulse-hero__ring-fill {
 stroke: var(--cc-critical);
}

.pulse-hero__score {
 position: absolute;
 inset: 0;
 display: flex;
 align-items: center;
 justify-content: center;
 transition: transform 0.3s ease;
}

.pulse-hero__score--animate {
 animation: score-bounce 0.6s ease;
}

.pulse-hero__number {
 font-size: 52px;
 font-weight: 900;
 color: var(--cc-text-primary);
 line-height: 1;
 font-variant-numeric: tabular-nums;
}

.pulse-hero__info {
 display: flex;
 flex-direction: column;
 gap: 6px;
}

.pulse-hero__badges-row {
 display: flex;
 align-items: center;
 gap: 14px;
 margin-top: 6px;
}

.pulse-hero__badge {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 4px 12px;
 border-radius: 20px;
 font-size: 11px;
 font-weight: 800;
