 background: var(--cc-bg-card);
 border: 1px solid var(--cc-border);
 position: relative;
 overflow: hidden;
}

.network-health::before {
 content: "";
 position: absolute;
 inset: 0;
 background: radial-gradient(ellipse at 25% 50%, rgba(0, 200, 150, 0.06), transparent 60%);
 pointer-events: none;
}

.network-health__content {
 display: flex;
 align-items: center;
 gap: 48px;
 position: relative;
 z-index: 1;
}

.network-health__gauge {
 position: relative;
 width: 180px;
 height: 180px;
 flex-shrink: 0;
}

.network-health__svg {
 width: 100%;
 height: 100%;
 transform: rotate(-90deg);
}

.network-health__ring-bg {
 fill: none;
 stroke: var(--cc-border);
 stroke-width: 8;
}

.network-health__ring-fill {
 fill: none;
 stroke: var(--cc-accent);
 stroke-width: 8;
 stroke-linecap: round;
 transition: stroke-dasharray 0.8s ease;
 filter: drop-shadow(0 0 6px rgba(0, 200, 150, 0.4));
}

.network-health__ring-inner {
 fill: none;
 stroke: rgba(0, 200, 150, 0.06);
 stroke-width: 2;
}

.network-health__gauge-center {
 position: absolute;
 inset: 0;
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 gap: 2px;
}

.network-health__gauge-percent {
 font-size: 36px;
 font-weight: 900;
 color: var(--cc-accent);
 line-height: 1;
 font-variant-numeric: tabular-nums;
}

.network-health__gauge-label {
 font-size: 9px;
 font-weight: 700;
 letter-spacing: 2px;
 color: var(--cc-text-secondary);
}

.network-health__pulse-ring {
 position: absolute;
 inset: -8px;
 border-radius: 50%;
 border: 1px solid rgba(0, 200, 150, 0.15);
 animation: network-pulse 3s ease-in-out infinite;
}

@keyframes network-pulse {
 0%, 100% {
 transform: scale(1);
 opacity: 0.4;
 }
 50% {
 transform: scale(1.05);
 opacity: 0.1;
 }
}
.network-health__info {
 flex: 1;
 display: flex;
 flex-direction: column;
 gap: 12px;
}

.network-health__title-row {
 display: flex;
 align-items: center;
 justify-content: space-between;
}

.network-health__section-label {
 font-size: 11px;
 font-weight: 700;
 letter-spacing: 1.5px;
 color: var(--cc-text-secondary);
 text-transform: uppercase;
}

.network-health__live-badge {
 font-size: 10px;
 font-weight: 700;
 color: var(--cc-accent);
 letter-spacing: 0.5px;
 animation: pulse-dot 1.5s ease-in-out infinite;
}

.network-health__status-row {
 display: flex;
 align-items: center;
 gap: 10px;
}

.network-health__status-dot {
 width: 12px;
 height: 12px;
 border-radius: 50%;
 background: var(--cc-accent);
 box-shadow: 0 0 8px rgba(0, 200, 150, 0.6);
 animation: pulse-dot 1.5s ease-in-out infinite;
}

.network-health__status-text {
 font-size: 28px;
 font-weight: 900;
 color: var(--cc-accent);
 letter-spacing: 2px;
}

.network-health__detail {
 font-size: 13px;
 color: var(--cc-text-secondary);
 font-weight: 500;
}

.network-health__bar-section {
 margin-top: 4px;
}

.network-health__bar-label {
 display: flex;
 justify-content: space-between;
 font-size: 12px;
 font-weight: 600;
 color: var(--cc-text-primary);
 margin-bottom: 6px;
}

.network-health__bar-percent {
 color: var(--cc-accent);
 font-weight: 700;
}

.network-health__bar-track {
 height: 8px;
 background: var(--cc-border);
 border-radius: 8px;
 overflow: hidden;
}

.network-health__bar-fill {
 height: 100%;
 background: linear-gradient(90deg, var(--cc-accent), #00e6a8);
 border-radius: 8px;
 transition: width 0.8s ease;
 box-shadow: 0 0 8px rgba(0, 200, 150, 0.3);
}

.network-health__stats {
 display: flex;
 gap: 24px;
 margin-top: 4px;
}

.network-health__stat {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.network-health__stat-value {
 font-size: 18px;
 font-weight: 800;
 color: var(--cc-accent);
 font-variant-numeric: tabular-nums;
}

.network-health__stat-value--warning {
 color: var(--cc-warning);
}

.network-health__stat-label {
 font-size: 10px;
 font-weight: 600;
 color: var(--cc-text-secondary);
 text-transform: uppercase;
 letter-spacing: 0.5px;
}',"style"),insertStyle(".critical-alerts__header {
 display: flex;
 justify-content: space-between;
