 border-radius: 10px;
 border-left: 3px solid transparent;
}

.critical-alerts__item--critical {
 border-left-color: var(--cc-critical);
}

.critical-alerts__item--high {
 border-left-color: var(--cc-warning);
}

.critical-alerts__item--medium {
