 font-size: 14px;
 color: var(--cc-text-primary);
}

.ai-panel__status {
 font-size: 11px;
 padding: 3px 10px;
 border-radius: 20px;
 background: rgba(245, 158, 11, 0.15);
 color: var(--cc-warning);
