 margin-bottom: 18px;
 padding: 14px;
 background: rgba(0, 0, 0, 0.2);
 border-radius: 10px;
}

.ai-panel__metric {
 display: flex;
 flex-direction: column;
 align-items: center;
 gap: 6px;
}

.ai-panel__metric-value {
 font-size: 20px;
 font-weight: 800;
 line-height: 1;
}

.ai-panel__metric-value--green {
 color: var(--cc-accent);
}

.ai-panel__metric-value--blue {
 color: var(--cc-blue);
}

.ai-panel__metric-label {
 font-size: 10px;
 font-weight: 600;
 color: var(--cc-text-secondary);
 text-transform: uppercase;
 letter-spacing: 0.5px;
}

.ai-panel__ring {
 position: relative;
 width: 44px;
 height: 44px;
}

.ai-panel__svg {
 width: 100%;
 height: 100%;
 transform: rotate(-90deg);
}

.ai-panel__ring-bg {
 fill: none;
 stroke: var(--cc-border);
 stroke-width: 3;
}

.ai-panel__ring-fill {
 fill: none;
 stroke: var(--cc-accent);
 stroke-width: 3;
 stroke-linecap: round;
}

.ai-panel__ring-text {
 position: absolute;
 inset: 0;
