 gap: 14px;
}

.city-heatmap__legend-item {
 display: flex;
 align-items: center;
 gap: 5px;
 font-size: 10px;
 color: var(--cc-text-secondary);
 font-weight: 600;
}

.city-heatmap__legend-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 display: inline-block;
}

.city-heatmap__stats {
 display: flex;
 gap: 16px;
 margin-bottom: 16px;
 padding: 10px 14px;
 background: rgba(255, 255, 255, 0.02);
 border-radius: 8px;
}

.city-heatmap__stat {
 font-size: 12px;
 font-weight: 700;
 color: var(--cc-text-secondary);
}

.city-heatmap__stat--green {
 color: var(--cc-accent);
}

.city-heatmap__stat--red {
 color: var(--cc-critical);
}

.city-heatmap__grid {
 display: flex;
 flex-direction: column;
 gap: 12px;
}

.city-heatmap__row {
 display: flex;
 align-items: center;
 justify-content: space-between;
}

.city-heatmap__name {
 font-size: 13px;
 color: var(--cc-text-primary);
 font-weight: 500;
 min-width: 120px;
}

.city-heatmap__dots {
 display: flex;
 gap: 8px;
}

.city-heatmap__dot {
 width: 16px;
 height: 16px;
 border-radius: 50%;
 display: inline-block;
 transition: transform 0.2s ease;
 cursor: pointer;
}

.city-heatmap__dot:hover {
 transform: scale(1.3);
}

.city-heatmap__dot--critical {
 animation: pulse-dot 2s ease-in-out infinite;
